import h5py as h
import numpy as np

fn = P/'pcam/training_split.h5' ; fn

with h.File(fn, 'r') as f: print(list(f.items()))

from PIL import Image
def _get_hd5_2_pil(idx, fn=P/'pcam/training_split.h5', col='x') -> Image:
  with h.File(fn, 'r') as f:
    img_arr = f[col][idx]
    if len(img_arr.shape) == 3 and img_arr.shape[-1] == 1: img_arr = (img_arr.squeeze()*255).astype(np.uint8)
  return Image.fromarray(img_arr)

